export function larguraDaCostaOriginal(id        )                     {
  const costa = COSTAS_APROVADAS[id];
  return costa === undefined ? undefined : Number(costa.split(':', 1)[0]);
}

export function costaAprovada(id        , mapa                   )          {
  return COSTAS_APROVADAS[id] === assinaturaDaCosta(mapa);
}
